-- Endor: An Empire Divided's NPC camps (docs/SPAWNS.md, roadmap step 3).
-- Written by tools/reference/npc_camps_sql.py --guide ed; edit that, not
-- this.
--
-- The planet's hostile, non-faction NPCs in An Empire Divided's tables
-- (pp. 428-440; mmoserverdb/reference/prima_ed/npcs.csv): those above level 11
-- and those the 2004 guide's table lacks. Each a template with the book's
-- stats, the client's model and name, and a weapon; each group in camps of
-- up to six kinds by level, 4 of each, placed at random on the planet in
-- the band of its strongest NPC's level, named after the group's camp in
-- the client's lair_n, each the client's camp building for the group where
-- the client has one, with an invisible lair (nothing to destroy).
--
-- Reconstructed, and data to tune: the book gives no weapons, so each NPC
-- carries one by group (Tusken rifles, Jawa ion rifles, stone knives for
-- the tribes, vibroblades for the Nightsisters and the Singing Mountain
-- clan) or by level (pistol below 15, carbine to 29, rifle above); models
-- for NPCs the client has no outfit of their own for (the group's);
-- splitting large groups by level; the camps. Camps call 4 at a time.
--
--   endor_jinda_tribesman_neutral_none            up to lvl 15 2500 m+    adept Jinda shaman (10, knife_stone), Jinda ritualist (10, knife_stone), Jinda elder (15, knife_stone), Jinda elder worker (15, knife_stone), Jinda loremaster (15, knife_stone), Jinda outcast (15, knife_stone); pp. 428, 434
--   endor_jinda_tribesman_neutral_none            up to lvl 35 3500 m+    Jinda shaman (20, knife_stone), weathered Jinda shaman (20, knife_stone), wise Jinda ritualist (20, knife_stone), gifted Jinda shaman (30, knife_stone), hardened Jinda warrior (30, knife_stone), Jinda tribesman (35, knife_stone); pp. 432, 434, 440
--   endor_jinda_warrior_neutral_none              up to lvl 40 3500 m+    Jinda veteran (35, knife_stone), masterful Jinda warrior (35, knife_stone), proficient Jinda worker (35, knife_stone), Jinda matriarch (40, knife_stone), Jinda warrior (40, knife_stone), seasoned Jinda warrior (40, knife_stone); pp. 434, 436, 438
--   endor_jinda_warrior_neutral_none              up to lvl 60 4500 m+    skilled Jinda worker (40, knife_stone), competent Jinda ritualist (50, knife_stone), Jinda worker (50, knife_stone), Jinda chief (55, knife_stone), archaic Jinda ritualist (60, knife_stone); pp. 428, 430, 434, 436, 440
--   endor_panshee_ritualist_neutral_small_theater up to lvl 30 3500 m+    Panshee ritualist (5, knife_stone), adept Panshee shaman (10, knife_stone), gifted Panshee shaman (10, knife_stone), hardened Panshee warrior (15, knife_stone), Panshee loremaster (25, knife_stone), Panshee shaman (30, knife_stone); pp. 428, 432, 434, 438
